-- ARC · Recetas de nachos (proteicos y caseros)
insert into public.content_recipes (id, slot, mode, name, items, how, steps, plate, tupper, active, sort) values
  ('rl20', 'cena', 'sanji', 'Nachos proteicos de ternera al horno', $arc$[["tortillaMaiz", "c"], ["terneraPicada", "p"], ["mozzarella", 20], ["guacamole", "f"], ["tomateFrito", 40], ["verduras", 80]]$arc$::jsonb,
   'Tortillas de maíz cortadas en triángulos y horneadas hasta que crujan, con ternera picada, tomate, un poco de mozzarella gratinada, guacamole y pico de gallo.',
   $arc$["Corta las tortillas de maíz en triángulos, ponlas en la bandeja sin aceite y hornéalas 8-10 minutos a 200 °C hasta que estén crujientes. Vigílalas: se queman rápido.", "Mientras, haz la ternera picada en la sartén con sal, pimentón, comino y un poco de ajo en polvo. Añade el tomate frito al final.", "Echa la carne sobre los nachos, reparte la mozzarella y gratina 2-3 minutos.", "Pica tomate, cebolla y cilantro con un poco de limón (pico de gallo) y ponlo por encima con el guacamole."]$arc$::jsonb, '', false, true, 119),
  ('rl21', 'comida', 'sencilla', 'Nachos de pollo con dip de yogur', $arc$[["tortillaMaiz", "c"], ["tirasPollo", "p"], ["yogurProt", 80], ["guacamole", "f"], ["verduras", 80]]$arc$::jsonb,
   'Nachos caseros de tortilla de maíz con tiras de pollo especiadas, dip de yogur proteico con lima y ajo, guacamole y pico de gallo.',
   $arc$["Corta las tortillas de maíz en triángulos y hornéalas 8-10 minutos a 200 °C, o 5-6 minutos en la freidora de aire, hasta que crujan.", "Saltea las tiras de pollo con pimentón, comino, sal y un chorrito de lima.", "Para el dip: yogur proteico con zumo de lima, sal, ajo en polvo y un poco de cilantro o perejil.", "Monta: nachos, pollo, pico de gallo (tomate y cebolla picados) y guacamole. El dip, aparte para mojar."]$arc$::jsonb, '', false, true, 120)
on conflict (id) do update set items = excluded.items, how = excluded.how, steps = excluded.steps, name = excluded.name;
